def quote_identifier_token(identifier):
    """Escapes schema.table.column identifiers for ANSI SQL dialect."""
    if isinstance(identifier, list):
        # Handle composite keys by quoting each element and joining with commas
        return ", ".join(f'"{p}"' for p in identifier)

    # Handle single identifier (string)
    parts = identifier.split(".")
    return ".".join(f'"{p}"' for p in parts)

