from typing import Any, Optional

class BaseField:
    """Base class for custom schema fields."""
    def __init__(self, allow_null: bool = False):
        self.allow_null = allow_null

    def run_parse(self, value: Any) -> Optional[Any]:
        """Parses and validates the input value."""
        if value is None:
            if self.allow_null:
                return None
            raise ValueError("Value cannot be null")
        return value

class DecimalQuotaField(BaseField):
    """Specialized field for storage quota limits."""
    def __init__(self, allow_null: bool = False):
        super().__init__(allow_null=allow_null)

    def run_parse(self, value: Any) -> Optional[float]:
        """Parses the input value into a float, handling null if allowed."""
        if value is None:
            if self.allow_null:
                return None
            raise ValueError("Quota value cannot be null")

        try:
            return float(value)
        except (ValueError, TypeError):
            raise ValueError("Invalid quota format. Must be a number.")

    def format_display(self, val: Optional[float]) -> str:
        if val is None:
            return "N/A"
        return f"{val:.2f} GB"
