class IncrementalUTF8Decoder:
    """Decodes arbitrary byte slices into UTF-8 strings."""
    def __init__(self):
        self.buffer = b''

    def decode_frame(self, raw_bytes):
        self.buffer += raw_bytes
        try:
            # Attempt to decode the entire buffer. If successful, clear the buffer.
            return self.buffer.decode("utf-8", errors="strict")
        except UnicodeDecodeError:
            # If decoding fails, it means the sequence is incomplete.
            # Keep the buffer as is and return an empty string.
            return ""
